"""Enumerate subalgebras of M_d(F_p) containing 1 that are generated by at most
`k` extra elements.  Every unital algebra of dimension <= d+1 embeds in M_d... more
precisely every unital algebra A of dimension n embeds in M_n(F_p) via the regular
representation, so all n-dimensional unital algebras occur among the n-dimensional
subalgebras of M_n(F_p) (generated by 1 and n-1 further elements)."""
import itertools
from linmod import span_basis, rank


def matmul(p, A, B, d):
    return [[sum(A[i][k] * B[k][j] for k in range(d)) % p for j in range(d)] for i in range(d)]


def closure(p, gens, d):
    """Basis of the subalgebra generated by gens (list of dxd matrices) and 1."""
    ident = [[1 if i == j else 0 for j in range(d)] for i in range(d)]
    basis = span_basis([list(map(list, g)) and [x for row in g for x in row] for g in gens] +
                       [[x for row in ident for x in row]], p, d * d)
    changed = True
    while changed:
        changed = False
        mats = [unflat(v, d) for v in basis]
        for X in mats:
            for Y in mats:
                Z = matmul(p, X, Y, d)
                zv = [x for row in Z for x in row]
                if rank(basis + [zv], p, d * d) > len(basis):
                    basis = span_basis(basis + [zv], p, d * d)
                    changed = True
    return basis


def unflat(v, d):
    return [v[i * d:(i + 1) * d] for i in range(d)]


def all_mats(p, d):
    out = []
    for flat in itertools.product(range(p), repeat=d * d):
        out.append([list(flat[i * d:(i + 1) * d]) for i in range(d)])
    return out


def enumerate_subalgebras(p, d, target_dims, k):
    """Yield (basis as list of matrices) for every subalgebra A <= M_d(F_p) with 1 in A,
    dim A in target_dims, generated by 1 and at most k further elements."""
    mats = all_mats(p, d)
    ident = [[1 if i == j else 0 for j in range(d)] for i in range(d)]
    others = [M for M in mats if M != ident]
    seen = set()
    for r in range(1, k + 1):
        for gens in itertools.combinations(others, r):
            basis = closure(p, list(gens), d)
            if len(basis) not in target_dims:
                continue
            key = tuple(sorted(tuple(v) for v in basis))
            if key in seen:
                continue
            seen.add(key)
            yield [unflat(v, d) for v in basis]
